-- J8: READ ONLY, Development tnipyxnvhgelwdpykyez only. Never rerun installation.
-- First result: fresh raw observation. Second result: ONLY three new function
-- definition hashes normalized for the independently observed CRLF paste effect.
-- No global schema normalization or permission/data exceptions.
BEGIN READ ONLY;
SET LOCAL statement_timeout='15s';
SET LOCAL lock_timeout='2s';
SELECT jsonb_build_object('observed_at',clock_timestamp(),'schema_md5',md5((jsonb_build_object(
 'ledger',(SELECT coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version),'[]') FROM supabase_migrations.schema_migrations),
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'rls',c.relrowsecurity,'force',c.relforcerowsecurity) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND (n.nspname='public' OR (n.nspname='storage' AND c.relname='objects'))),
 'columns',(SELECT jsonb_agg(to_jsonb(x) ORDER BY table_name,ordinal_position) FROM (SELECT table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,column_default FROM information_schema.columns WHERE table_schema='public') x),
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition_md5',md5(pg_get_functiondef(p.oid)),'definer',p.prosecdef,'settings',p.proconfig,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')),
 'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY schemaname,tablename,policyname) FROM (SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname IN ('public','storage')) x),
 'indexes',(SELECT jsonb_agg(to_jsonb(x) ORDER BY tablename,indexname) FROM (SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='public') x),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conrelid::regclass::text,c.conname) FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='public'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal),
 'grants',(SELECT jsonb_agg(to_jsonb(x) ORDER BY table_name,column_name,grantee,privilege_type) FROM (SELECT table_name,column_name,grantee,privilege_type,is_grantable FROM information_schema.column_privileges WHERE table_schema='public' AND grantee IN ('PUBLIC','anon','authenticated','service_role')) x),
 'table_privileges',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'role',r.role,'privilege',v.privilege,'allowed',has_table_privilege(r.role,c.oid,v.privilege)) ORDER BY c.relname,r.role,v.privilege) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (VALUES ('anon'),('authenticated'),('service_role')) r(role) CROSS JOIN (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) v(privilege) WHERE n.nspname='public' AND c.relkind='r'),
 'postgres_public_defaults',(SELECT coalesce(jsonb_agg(jsonb_build_object('kind',d.defaclobjtype,'acl',d.defaclacl::text) ORDER BY d.defaclobjtype),'[]') FROM pg_default_acl d JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname='public' AND pg_get_userbyid(d.defaclrole)='postgres'),
 'public_event_triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.evtname,'event',e.evtevent,'enabled',e.evtenabled,'function',e.evtfoid::regprocedure::text,'tags',e.evttags) ORDER BY e.evtname),'[]') FROM pg_event_trigger e JOIN pg_proc p ON p.oid=e.evtfoid JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'),
 'buckets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) ORDER BY id),'[]') FROM storage.buckets)))::text),'taxonomy_md5',md5(((SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM
 (SELECT id,parent_id,name,level,is_active,lifecycle_state,is_assignable,policy_class,professional_review_status,taxonomy_version
 FROM public.categories) x))::text),'catalog_md5',md5(jsonb_build_object(
 'products',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY id),'[]') FROM public.products p),
 'brands',(SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY id),'[]') FROM public.brands b),
 'identity',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY product_id),'[]') FROM public.product_identity i),
 'identifiers',(SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY gtin),'[]') FROM public.product_identifiers g))::text),'ledger',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',cardinality(statements),'source_sha256_lf',encode(sha256(convert_to(replace(array_to_string(statements,''),chr(13)||chr(10),chr(10)),'UTF8')),'hex')) ORDER BY version) FROM supabase_migrations.schema_migrations),'data',jsonb_build_object('categories',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.categories x),
'products',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.products x),
'brands',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.brands x),
'product_identity',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.product_identity x),
'product_identifiers',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.product_identifiers x),
'product_submissions',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.product_submissions x),
'product_submission_decisions',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.product_submission_decisions x),
'catalog_media_config',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.catalog_media_config x),
'shops',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.shops x),
'profiles',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.profiles x),
'shop_products',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.shop_products x),
'notifications',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]')::text)) FROM public.notifications x)),'public_tables',(SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r'),'all_public_rls',(SELECT bool_and(c.relrowsecurity) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r'),'decisions_enabled',(SELECT decisions_enabled FROM public.catalog_media_config),'production_canonical_absent',to_regclass('public.canonical_categories') IS NULL,'receipt_count',(SELECT count(*) FROM public.catalog_publication_batches),'receipt_rls',(SELECT relrowsecurity FROM pg_class WHERE oid='public.catalog_publication_batches'::regclass),'private_helpers',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definer',p.prosecdef,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('_catalog_publication_immutable_v1','_catalog_price_contract_guard_v1','_publish_catalog_submission_v1')),'receipt_client_privileges',(SELECT jsonb_agg(jsonb_build_object('role',r.role,'privilege',v.privilege,'allowed',has_table_privilege(r.role,'public.catalog_publication_batches',v.privilege)) ORDER BY r.role,v.privilege) FROM (VALUES('anon'),('authenticated'),('service_role')) r(role) CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) v(privilege)))::text AS installation_observation;
ROLLBACK;

BEGIN READ ONLY;
SET LOCAL statement_timeout='15s';
SET LOCAL lock_timeout='2s';
WITH snapshot AS (SELECT jsonb_build_object(
 'ledger',(SELECT coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version),'[]') FROM supabase_migrations.schema_migrations),
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'rls',c.relrowsecurity,'force',c.relforcerowsecurity) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND (n.nspname='public' OR (n.nspname='storage' AND c.relname='objects'))),
 'columns',(SELECT jsonb_agg(to_jsonb(x) ORDER BY table_name,ordinal_position) FROM (SELECT table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,column_default FROM information_schema.columns WHERE table_schema='public') x),
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition_md5',md5(pg_get_functiondef(p.oid)),'definer',p.prosecdef,'settings',p.proconfig,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')),
 'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY schemaname,tablename,policyname) FROM (SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname IN ('public','storage')) x),
 'indexes',(SELECT jsonb_agg(to_jsonb(x) ORDER BY tablename,indexname) FROM (SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='public') x),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conrelid::regclass::text,c.conname) FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='public'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal),
 'grants',(SELECT jsonb_agg(to_jsonb(x) ORDER BY table_name,column_name,grantee,privilege_type) FROM (SELECT table_name,column_name,grantee,privilege_type,is_grantable FROM information_schema.column_privileges WHERE table_schema='public' AND grantee IN ('PUBLIC','anon','authenticated','service_role')) x),
 'table_privileges',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'role',r.role,'privilege',v.privilege,'allowed',has_table_privilege(r.role,c.oid,v.privilege)) ORDER BY c.relname,r.role,v.privilege) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (VALUES ('anon'),('authenticated'),('service_role')) r(role) CROSS JOIN (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) v(privilege) WHERE n.nspname='public' AND c.relkind='r'),
 'postgres_public_defaults',(SELECT coalesce(jsonb_agg(jsonb_build_object('kind',d.defaclobjtype,'acl',d.defaclacl::text) ORDER BY d.defaclobjtype),'[]') FROM pg_default_acl d JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname='public' AND pg_get_userbyid(d.defaclrole)='postgres'),
 'public_event_triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.evtname,'event',e.evtevent,'enabled',e.evtenabled,'function',e.evtfoid::regprocedure::text,'tags',e.evttags) ORDER BY e.evtname),'[]') FROM pg_event_trigger e JOIN pg_proc p ON p.oid=e.evtfoid JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'),
 'buckets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) ORDER BY id),'[]') FROM storage.buckets)) AS schema), new_functions AS (
 SELECT p.oid::regprocedure::text signature,pg_get_functiondef(p.oid) definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('_catalog_price_contract_guard_v1','_catalog_publication_immutable_v1','_publish_catalog_submission_v1')
), normalized AS (SELECT jsonb_set(schema,'{functions}',(SELECT jsonb_agg(CASE WHEN n.signature IS NULL THEN f ELSE jsonb_set(f,'{definition_md5}',to_jsonb(md5(replace(n.definition,chr(13)||chr(10),chr(10))))) END ORDER BY f->>'signature') FROM jsonb_array_elements(schema->'functions') f LEFT JOIN new_functions n ON n.signature=f->>'signature')) AS schema FROM snapshot)
SELECT jsonb_build_object('raw_schema_md5',(SELECT md5(schema::text) FROM snapshot),'only_three_new_functions_lf_schema_md5',(SELECT md5(schema::text) FROM normalized),'functions',(SELECT jsonb_agg(jsonb_build_object('signature',signature,'definition_md5',md5(definition),'lf_md5',md5(replace(definition,chr(13)||chr(10),chr(10))),'cr_count',length(definition)-length(replace(definition,chr(13),''))) ORDER BY signature) FROM new_functions))::text AS installation_observation;
ROLLBACK;
